namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public int DepartmentId { get; set; }
    public string DepartmentName { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string Instructor { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Name is required.")]
    [StringLength(100)]
    public string StudentName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Z0-9]{6,10}$", ErrorMessage = "Student ID must be 6-10 uppercase alphanumeric characters.")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Study of numbers, structures, and patterns." },
            new() { Id = 3, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and fundamental forces." },
            new() { Id = 4, Name = "English", Code = "ENG", Description = "Study of literature, writing, and rhetoric." },
            new() { Id = 5, Name = "History", Code = "HIST", Description = "Study of past events and civilizations." },
        };

        _courses = new List<Course>
        {
            new() { Id = 1, Title = "Introduction to Programming", Code = "CS 101", DepartmentId = 1, DepartmentName = "Computer Science", Description = "Learn the fundamentals of programming using Python. Topics include variables, control flow, functions, and basic data structures.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Instructor = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and computer science education. She holds a PhD from MIT.", IsFeatured = true },
            new() { Id = 2, Title = "Data Structures & Algorithms", Code = "CS 201", DepartmentId = 1, DepartmentName = "Computer Science", Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs) and algorithm design techniques.", Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", Instructor = "Dr. James Park", InstructorBio = "Dr. Park specializes in algorithm optimization and has published extensively in computational complexity theory." },
            new() { Id = 3, Title = "Database Systems", Code = "CS 340", DepartmentId = 1, DepartmentName = "Computer Science", Description = "Relational database design, SQL, normalization, transaction processing, and distributed databases.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", Instructor = "Prof. Maria Rodriguez", InstructorBio = "Prof. Rodriguez worked at Oracle for a decade before joining academia. Her research focuses on query optimization." },
            new() { Id = 4, Title = "Calculus I", Code = "MATH 151", DepartmentId = 2, DepartmentName = "Mathematics", Description = "Limits, derivatives, and integrals of single-variable functions with applications.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Instructor = "Dr. Robert Liu", InstructorBio = "Dr. Liu is an award-winning educator with research interests in differential equations and mathematical modeling.", IsFeatured = true },
            new() { Id = 5, Title = "Linear Algebra", Code = "MATH 220", DepartmentId = 2, DepartmentName = "Mathematics", Description = "Vector spaces, matrices, determinants, eigenvalues, and linear transformations.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", Instructor = "Dr. Emily Watson", InstructorBio = "Dr. Watson's research bridges pure mathematics and machine learning applications." },
            new() { Id = 6, Title = "General Physics I", Code = "PHYS 101", DepartmentId = 3, DepartmentName = "Physics", Description = "Mechanics, thermodynamics, and waves. Includes weekly lab sessions.", Credits = 4, Schedule = "Tue/Thu 9:00–10:20 AM + Lab Fri 1:00–3:00 PM", Instructor = "Dr. Alan Foster", InstructorBio = "Dr. Foster is an experimental physicist with expertise in particle physics and science communication.", IsFeatured = true },
            new() { Id = 7, Title = "Quantum Mechanics", Code = "PHYS 301", DepartmentId = 3, DepartmentName = "Physics", Description = "Wave functions, Schrödinger equation, quantum states, and measurement theory.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", Instructor = "Dr. Priya Sharma", InstructorBio = "Dr. Sharma conducts research in quantum computing and has collaborated with leading national laboratories." },
            new() { Id = 8, Title = "English Composition", Code = "ENG 101", DepartmentId = 4, DepartmentName = "English", Description = "Develop clear, effective writing skills through essays, research papers, and peer review.", Credits = 3, Schedule = "Mon/Wed 9:00–10:20 AM", Instructor = "Prof. Daniel Hayes", InstructorBio = "Prof. Hayes is a published author and writing coach with expertise in academic and creative writing." },
            new() { Id = 9, Title = "American Literature", Code = "ENG 250", DepartmentId = 4, DepartmentName = "English", Description = "Survey of American literary works from the colonial period to the present.", Credits = 3, Schedule = "Tue/Thu 2:30–3:50 PM", Instructor = "Dr. Lisa Thompson", InstructorBio = "Dr. Thompson specializes in 20th-century American fiction and has authored three books on the subject.", IsFeatured = true },
            new() { Id = 10, Title = "World History to 1500", Code = "HIST 101", DepartmentId = 5, DepartmentName = "History", Description = "Major civilizations, cultural exchanges, and transformative events from prehistory through the medieval era.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", Instructor = "Dr. Michael Brown", InstructorBio = "Dr. Brown is an archaeologist and historian focusing on ancient Mediterranean civilizations." },
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public List<Course> SearchCourses(string? searchTerm, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Instructor.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetAllCourses() => _courses;
}

